  API --> MEDA[ Medaudit GEO API ]`},{id:41,title:"Pores & Wrinkles Detection Service",description:"Face texture analysis service that detects pores and wrinkles and returns labeled overlays and metrics.",longDescription:"Cosmetic face-texture pipeline using face landmarks, region masks, segmentation-based wrinkle and fine-line detection, skeletonized line traces, overlays, per-line CSV outputs, timing events, and visual quality gates. The public case study avoids diagnostic claims and focuses on the engineering path from image capture to reviewable overlays.",keyFeatures:["MediaPipe landmark-based ROI extraction and face-region masks","Segmentation-based wrinkle and fine-line tracing with skeleton overlays","Async job API with progress + results endpoints","Flutter demo client and Telegram Mini App UI for cosmetic analysis review"],techStack:["Python","FastAPI","MediaPipe","YOLO","ONNX","Cloud Run","Flutter","MLflow"],benchmarks:[{label:"API endpoints",value:"8",context:"/, /app, /tma, /v1/*, /healthz"},{label:"Tasks",value:"3",context:"pores, wrinkles, pores+wrinkles"},{label:"Image types",value:"5",context:"jpeg/png/webp/tiff/bmp"},{label:"Default imgsz",value:"1280",context:"segment endpoint default"}],links:[],mermaidDiagram:`flowchart LR
